/**
 * legge le route per caricarle nel router di laravel
 */
protected function load()
{
    $links = $this->loadProvider();

    $this->routes = [];

    if ($this->locales) {
        foreach ($this->locales as $locale => $label) {
            foreach ($links as $key => $value) {
                // non registro i valori vuoti
                if (!strlen($value["link_".$locale])) {
                    continue;
                }

                $isAbsolute = strpos($value["link_".$locale], 'http') === 0;

                $link = $isAbsolute ? $value["link_".$locale] : '/'.$locale.rtrim($value["link_".$locale], '/');

                $code = $value["code"].'_'.$locale;

                $link = [
                    "code" => $code,
                    "type" => $value["type"],
                    "link" => $link,
                    "handler" => $value["filename"],
                ];

                $this->routes[$code] = $link;
            }
        }
    } else {
        foreach ($links as $key => $value) {
            $link = $value["link"];

            $code = $value["code"];

            $this->routes[$code] = [
                "code" => $code,
                "type" => $value["type"],
                "link" => $link,
                "handler" => $value["filename"],
            ];
        }
    }

    return $this;
}


/**
 * registra le route assegnatele nel router di laravel
 */
public function register()
{
    if ($this->routes === null) {
        $this->load();
    }

    foreach ($this->routes as $code => $values) {
        // da allineare al locale
        $link = $values["link"];

        // trasformo in maiuscolo e in array valido per router
        $values["type"] = strtoupper($values["type"]);
        $values["type"] = explode(",", $values["type"]);

        /**
         * Handler vuoto o script
         */
        if (!strlen($values["handler"]) || pathinfo($values["handler"], PATHINFO_EXTENSION) == 'php') {
            $handler = $values["handler"];

            Route::addRoute($values["type"], $link, function () use ($handler, $code) {
                // recupero query stringa e l'aggiungo a $_GET
                $cps = parse_url($handler);

                $params = array();

                // aggiungo i parametri alla richiesta
                if (isset($cps["query"])) {
                    parse_str($cps["query"], $params);
                    request()->request->add($params);
                }

                // recupero il nome della view
                $viewName = str_replace(".blade.php", "", $handler);

                if (!view()->exists($viewName)) {
                    throw new Exception("La view non esiste, verifica di aver impostato un controller / file per il link.");
                }

                return view($viewName);
            })->name($code)->middleware("web");
        } else {

            $handler = $values['handler'];

            // se inizia con "\" assumo che sia un namespace assoluto e quindi lo lascio così com'è
            // TODO: refactoring
            // es. \App\Namespace\Controller
            if (strpos($handler, '\\') === 0) {

                // costruisco namespace completo se non è già assoluto(assumo App\Http\Controllers)
            } elseif (strpos($handler, 'App\Http\Livewire') === false && strpos($handler, 'App\Http\Controllers') === false) {
                $handler = 'App\Http\Controllers\\'.$handler;
            }

            Route::addRoute($values["type"], $link, $handler)->name($code)->middleware("web");

        }
    } // ciclo link
}


